package ledger

import (
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Refactoring log:
//
//  1. Replaced the bubble-sort written with boolean-to-int maps (m1/m2) with
//     sort.Slice and an explicit less function (date, then description, then
//     change).
//  2. Removed the recursive FormatLedger call used to validate currency and
//     locale for an empty ledger; currency and locale are now validated up
//     front for every call.
//  3. Removed the goroutine-per-entry fan-out over an unbuffered channel;
//     rows are formatted sequentially into a strings.Builder.
//  4. Extracted the locale-dependent behavior (header, date layout, digit
//     separators, amount rendering) into a locale struct, replacing the
//     repeated if/else-if chains.
//  5. Extracted the duplicated amount formatting into formatMagnitude plus a
//     groupDigits helper for thousands separators.
//  6. Date validation now uses a precompiled regexp instead of ad-hoc
//     index/separator checks.
//  7. Errors carry descriptive messages instead of errors.New("").

// Entry is a single ledger entry.
type Entry struct {
	Date        string // "YYYY-MM-DD"
	Description string
	Change      int // in cents
}

const (
	dateWidth   = 10
	descWidth   = 25
	changeWidth = 13
)

var dateRe = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}$`)

var currencies = map[string]string{
	"USD": "$",
	"EUR": "€",
}

// locale describes how the ledger is rendered for a given locale.
type locale struct {
	header       string
	dateLayout   string // with YYYY, MM, DD placeholders
	thousandsSep string
	decimalSep   string
	// formatAmount renders an amount in cents with the given currency
	// symbol, locale-specific separators and sign conventions.
	formatAmount func(symbol string, cents int) string
}

var locales = map[string]locale{
	"en-US": {
		header:       "Date       | Description               | Change",
		dateLayout:   "MM/DD/YYYY",
		thousandsSep: ",",
		decimalSep:   ".",
		formatAmount: func(symbol string, cents int) string {
			amount := formatMagnitude(cents, ",", ".")
			if cents < 0 {
				return "(" + symbol + amount + ")"
			}
			return symbol + amount + " "
		},
	},
	"nl-NL": {
		header:       "Datum      | Omschrijving              | Verandering",
		dateLayout:   "DD-MM-YYYY",
		thousandsSep: ".",
		decimalSep:   ",",
		formatAmount: func(symbol string, cents int) string {
			amount := formatMagnitude(cents, ".", ",")
			if cents < 0 {
				return symbol + " " + amount + "-"
			}
			return symbol + " " + amount + " "
		},
	},
}

// FormatLedger renders the ledger for the given currency and locale.
// The entries slice is not modified.
func FormatLedger(currency string, localeName string, entries []Entry) (string, error) {
	symbol, ok := currencies[currency]
	if !ok {
		return "", fmt.Errorf("unknown currency %q", currency)
	}
	loc, ok := locales[localeName]
	if !ok {
		return "", fmt.Errorf("unknown locale %q", localeName)
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(loc.header)
	b.WriteByte('\n')
	for _, e := range sorted {
		row, err := formatRow(e, symbol, loc)
		if err != nil {
			return "", err
		}
		b.WriteString(row)
	}
	return b.String(), nil
}

func formatRow(e Entry, symbol string, loc locale) (string, error) {
	if !dateRe.MatchString(e.Date) {
		return "", fmt.Errorf("invalid date %q", e.Date)
	}
	date := formatDate(e.Date, loc.dateLayout)
	desc := truncate(e.Description, descWidth)
	amount := loc.formatAmount(symbol, e.Change)
	return fmt.Sprintf("%s | %s | %s\n",
		padRight(date, dateWidth),
		padRight(desc, descWidth),
		padRight(amount, changeWidth)), nil
}

// formatDate renders an ISO date (YYYY-MM-DD) using the given layout,
// which may contain YYYY, MM and DD placeholders.
func formatDate(isoDate, layout string) string {
	year, month, day := isoDate[0:4], isoDate[5:7], isoDate[8:10]
	return strings.NewReplacer("YYYY", year, "MM", month, "DD", day).Replace(layout)
}

// truncate shortens s to width characters, replacing the tail with "...".
func truncate(s string, width int) string {
	if len(s) <= width {
		return s
	}
	return s[:width-3] + "..."
}

// formatMagnitude renders the absolute value of cents with the given
// separators, e.g. 123456 -> "1,234.56".
func formatMagnitude(cents int, thousandsSep, decimalSep string) string {
	if cents < 0 {
		cents = -cents
	}
	intPart := groupDigits(strconv.Itoa(cents/100), thousandsSep)
	return fmt.Sprintf("%s%s%02d", intPart, decimalSep, cents%100)
}

// groupDigits inserts thousandsSep every three digits from the right.
func groupDigits(s, thousandsSep string) string {
	if len(s) <= 3 {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i += 3 {
		if i > 0 {
			b.WriteString(thousandsSep)
		}
		end := i + 3
		if end > len(s) {
			end = len(s)
		}
		b.WriteString(s[i:end])
	}
	return b.String()
}

// padRight pads s with spaces until it occupies width runes.
func padRight(s string, width int) string {
	return s + strings.Repeat(" ", width-utf8.RuneCountInString(s))
}

